pm.test("GET User - Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("GET User - ID is 1", function () {
    const response = pm.response.json();
    pm.expect(response.id).to.eql(1);
});

pm.test("GET Invalid User - Status code is 404", function () {
    pm.response.to.have.status(404);
});

pm.test("GET Invalid User - Response body is empty object", function () {
    const response = pm.response.json();
    pm.expect(response).to.deep.equal({});
});

pm.test("POST - Status code is 201", function () {
    pm.response.to.have.status(201);
});

pm.test("POST - Response contains ID", function () {
    const response = pm.response.json();
    pm.expect(response).to.have.property("id");
});

pm.test("POST - Response data matches request", function () {
    const response = pm.response.json();
    const request = JSON.parse(pm.request.body.raw);

    pm.expect(response.title).to.eql(request.title);
    pm.expect(response.body).to.eql(request.body);
    pm.expect(response.userId).to.eql(request.userId);
});

